import { test, expect } from '@playwright/test';

test.describe('Search Race Condition Handling', () => {
  let baseUrl: string;

  test.beforeEach(async ({ page }) => {
    baseUrl = 'https://example.com';
    await page.goto(baseUrl);
  });

  test('should display only the latest search result when multiple searches are triggered rapidly', async ({ page }) => {
    // Navigate to search page
    await page.goto(`${baseUrl}/search`);

    // Get the search input field
    const searchInput = page.getByRole('searchbox');

    // Trigger multiple rapid searches without waiting for results
    await searchInput.fill('first');
    await page.waitForTimeout(100);

    await searchInput.fill('second');
    await page.waitForTimeout(100);

    await searchInput.fill('final');

    // Wait for the results to load
    await page.waitForTimeout(500);

    // Verify that only the latest search result is displayed
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    // Check that results contain only "final" related items
    const resultItems = page.getByRole('listitem');
    const count = await resultItems.count();

    // Verify we have results
    expect(count).toBeGreaterThan(0);

    // Verify the first result contains the latest search term
    const firstResult = resultItems.first();
    const resultText = await firstResult.textContent();
    expect(resultText).toContain('final');
  });

  test('should cancel previous search requests when a new search is initiated', async ({ page }) => {
    // Navigate to search page
    await page.goto(`${baseUrl}/search`);

    // Set up request interception to track which requests complete
    const completedRequests: string[] = [];

    page.on('response', async (response) => {
      if (response.url().includes('/api/search')) {
        const url = new URL(response.url());
        const query = url.searchParams.get('q');
        if (query) {
          completedRequests.push(query);
        }
      }
    });

    const searchInput = page.getByRole('searchbox');

    // Trigger first search
    await searchInput.fill('query1');
    await page.waitForTimeout(50);

    // Trigger second search before first completes
    await searchInput.fill('query2');
    await page.waitForTimeout(50);

    // Trigger third search
    await searchInput.fill('query3');

    // Wait for all network activity to settle
    await page.waitForLoadState('networkidle');

    // Verify that the displayed results match the latest query
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    const resultItems = page.getByRole('listitem');
    const firstResult = resultItems.first();
    const resultText = await firstResult.textContent();

    // The results should be for query3, not query1 or query2
    expect(resultText).toContain('query3');
  });

  test('should handle rapid search input changes without displaying stale results', async ({ page }) => {
    // Navigate to search page
    await page.goto(`${baseUrl}/search`);

    const searchInput = page.getByRole('searchbox');
    const clearButton = page.getByRole('button', { name: /clear/i });

    // First search
    await searchInput.fill('apple');
    await page.waitForTimeout(200);

    // Verify first results are shown
    let resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    let resultItems = page.getByRole('listitem');
    let firstResult = await resultItems.first().textContent();
    expect(firstResult).toContain('apple');

    // Clear and search for something different
    await clearButton.click();
    await searchInput.fill('banana');
    await page.waitForTimeout(200);

    // Verify results updated to latest search
    resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    resultItems = page.getByRole('listitem');
    firstResult = await resultItems.first().textContent();
    expect(firstResult).toContain('banana');

    // Verify old results are not present
    const allResults = await page.getByRole('listitem').allTextContents();
    const hasAppleResults = allResults.some(text => text.includes('apple'));
    expect(hasAppleResults).toBeFalsy();
  });

  test('should show loading state during search and clear it when results arrive', async ({ page }) => {
    // Navigate to search page
    await page.goto(`${baseUrl}/search`);

    const searchInput = page.getByRole('searchbox');

    // Start typing to trigger search
    await searchInput.fill('test');

    // Check for loading indicator
    const loadingIndicator = page.getByRole('status', { name: /loading/i });

    // Wait for loading to appear and then disappear
    try {
      await expect(loadingIndicator).toBeVisible({ timeout: 1000 });
      await expect(loadingIndicator).not.toBeVisible({ timeout: 5000 });
    } catch {
      // Loading might be too fast to catch, which is acceptable
    }

    // Verify results are displayed
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    const resultItems = page.getByRole('listitem');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);
  });
});
